// Parses one raw Sheet row (as written by yardi_export.py's header names)
// into the fields the rest of this workflow needs. Mirrors the same
// regex-based email/phone extraction the Python script itself uses on
// TENANT CONTACT, since the Sheet only has that field pre-flattened to a
// single string (no separate email/phone columns).
//
// The native Google Sheets node's "read" operation auto-detects the first
// row as headers, so each item here is already keyed by the Sheet's own
// column names (TENANT, TENANT CONTACT, PROPERTY, etc.) -- no separate
// grid-parsing step needed.
//
// UPDATED 2026-08-13: Yardi's "Tenant Direct" contact type is sometimes
// phone-only -- no email at all. Confirmed live on a real lead, "Luis F.",
// whose TENANT CONTACT was just "Luis F.\nTenant Direct\n4706365654\n".
// The old version required an email and silently dropped anything without
// one -- not even left for manual review, just gone. Now a row is only
// dropped if it has NEITHER an email NOR a phone number.

const out = [];

for (const item of $input.all()) {
  const row = item.json;
  const tenant = (row['TENANT'] || '').toString().trim();
  if (!tenant) continue; // skip any stray blank rows

  const rawContact = (row['TENANT CONTACT'] || '').toString();
  const emailMatch = rawContact.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  const phoneMatch = rawContact.match(/\b\d{10}\b|\b\d{3}[-.]\d{3}[-.]\d{4}\b/);

  const email = emailMatch ? emailMatch[0].toLowerCase() : '';
  const phoneDigits = phoneMatch ? phoneMatch[0].replace(/\D/g, '') : '';

  // A row needs SOME usable contact info (email or phone) to sync -- no way
  // to reach the contact means no reliable way to dedupe either, and fuzzy
  // name-matching already proved unsafe (see the 'Mark Lopez' false match
  // from the manual backfill comparison). Those rows just stay visible in
  // the Sheet for a manual look instead.
  if (!email && !phoneDigits) continue;

  out.push({
    json: {
      tenant,
      email,
      phone: phoneDigits,
      // Dedup key used downstream: email when we have one, otherwise the
      // digits-only phone. Keeping this as its own field means the dedup
      // query node doesn't need to re-derive the email-vs-phone choice.
      dedupe_field: email ? 'email' : 'phone_digits',
      dedupe_value: email || phoneDigits,
      first_name: tenant.split(/[ ,]+/)[0] || '',
      property: (row['PROPERTY'] || '').toString(),
      address: (row['PROPERTY ADDRESS'] || '').toString(),
      stage_raw: (row['STAGE'] || '').toString(),
      sub_stage: (row['SUB STAGE'] || '').toString(),
      last_activity_comment: (row['LAST ACTIVITY COMMENT'] || '').toString(),
      date_created: (row['DATE CREATED'] || '').toString(),
    },
  });
}

return out;

// Firestore's runQuery returns an array of result entries per call. "Query
// Firestore for existing email" fires one call per input item, in the same
// order Parse Rows emitted them, so queryResults[i] always corresponds to
// parsedLeads[i]. This node runs once for ALL items (n8n Code node's
// default execution mode) and must return one output item per input item.
//
// BUG FOUND LIVE 2026-08-11: an earlier version used $input.first() and
// $(...).item (singular), which only ever look at the FIRST item -- with
// multiple rows in the Sheet, that silently dropped every row after the
// first from the sync with no error (the execution still reported
// "success", it just produced 1 output instead of N). Looping over every
// item explicitly here is the fix.

const queryResults = $input.all();
const parsedLeads = $('Parse Rows (extract email/phone)').all();

const out = [];
for (let i = 0; i < queryResults.length; i++) {
  const raw = queryResults[i].json;
  const body = Array.isArray(raw) ? raw : [raw];
  const matched = body.some((r) => r && r.document);
  const lead = (parsedLeads[i] && parsedLeads[i].json) || {};
  out.push({ json: { ...lead, matched } });
}
return out;
